/* Fontes embutidas (SIL Open Font License): Archivo, Archivo Narrow e IBM Plex Mono, subconjunto latino.
   Ficam dentro do JS para funcionar offline, abrindo o index.html direto e dentro do SVG usado no PDF. */
window.QFD = window.QFD || {};
(function (Q) {
  'use strict';
  Q.FONTS = [
    { family: 'Archivo', weight: 400, data: '' },
    { family: 'Archivo', weight: 600, data: '' },
    { family: 'Archivo', weight: 700, data: '' },
    { family: 'Archivo Narrow', weight: 400, data: '' },
    { family: 'Archivo Narrow', weight: 600, data: '' },
    { family: 'IBM Plex Mono', weight: 400, data: '' },
    { family: 'IBM Plex Mono', weight: 600, data: '' }
  ];
  Q.fontFaceCSS = function (only) {
    return Q.FONTS.filter(function (f) { return !only || only.indexOf(f.family) >= 0; }).map(function (f) {
      return '@font-face{font-family:"' + f.family + '";font-style:normal;font-weight:' + f.weight + ';font-display:swap;src:url(data:font/woff2;base64,' + f.data + ') format("woff2")}';
    }).join('');
  };
  const st = document.createElement('style');
  st.id = 'qfd-fonts';
  st.textContent = Q.fontFaceCSS();
  document.head.appendChild(st);
})(window.QFD);
